package cn.local.rainreminder;
import android.app.job.*;import android.content.*;import android.os.Build;
public class WidgetCheckJob extends JobService {
 static final int ID=2021;Scanner scanner;
 static boolean pending(Context c){long until=Store.prefs(c).getLong("widgetCheckUntil",0);return until>System.currentTimeMillis();}
 static void request(Context c){if(Scanner.running()||pending(c))return;Store.prefs(c).edit().putLong("widgetCheckUntil",System.currentTimeMillis()+9*60000).putString("widgetProgress","正在等待网络与系统调度…").putString("status","等待后台检查作业").apply();JobScheduler scheduler=c.getSystemService(JobScheduler.class);int result=JobScheduler.RESULT_FAILURE;try{JobInfo.Builder builder=new JobInfo.Builder(ID,new ComponentName(c,WidgetCheckJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY);if(Build.VERSION.SDK_INT>=31)builder.setExpedited(true);result=scheduler.schedule(builder.build());}catch(RuntimeException ignored){}if(result!=JobScheduler.RESULT_SUCCESS)try{result=scheduler.schedule(new JobInfo.Builder(ID,new ComponentName(c,WidgetCheckJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setOverrideDeadline(1000).build());}catch(RuntimeException ignored){}if(result!=JobScheduler.RESULT_SUCCESS){Store.prefs(c).edit().remove("widgetCheckUntil").remove("widgetProgress").apply();Store.status(c,"检查失败：系统暂不能安排后台检查，请打开应用重试");}RainWidget.updateAll(c);}
 public boolean onStartJob(JobParameters params){if(Scanner.running()){clear(this);RainWidget.updateAll(this);return false;}if(Store.prefs(this).getLong("last",0)<=0){failed("请先登录长江雨课堂");return false;}scanner=new Scanner(this,new Scanner.Listener(){public void progress(String value){Store.prefs(WidgetCheckJob.this).edit().putString("widgetProgress",value).apply();RainWidget.updateAll(WidgetCheckJob.this);}public void done(boolean ok,String message){if(!ok)failed(message);else clear(WidgetCheckJob.this);RainWidget.updateAll(WidgetCheckJob.this);scanner=null;jobFinished(params,false);}},false);scanner.start();return true;}
 void failed(String message){clear(this);Store.status(this,"检查失败："+message);RainWidget.updateAll(this);Store.notify(this,"作业检查需要处理",message+"；点击打开应用。原作业记录保留。");}
 static void clear(Context c){Store.prefs(c).edit().remove("widgetCheckUntil").remove("widgetProgress").apply();}
 public boolean onStopJob(JobParameters params){if(scanner!=null){scanner.cancel();scanner=null;failed("后台检查被系统中断，请重试");}return false;}
}
